//! `snapshots list | create | delete`.
//!
//! Calls: privd `ListSnapshots`, `CreateSnapshot`, `DeleteSnapshot`. Names are generated by privd
//! and shown sanitized; the CLI validates a name for `delete` against the contract's pattern
//! before sending (privd checks again).

use hx_ipc::privd::pb::{self, request::Command, response::Result as R};
use serde_json::{Value, json};

use super::{enum_name, privd};
use crate::cli::error::CliError;
use crate::cli::privd::unexpected;
use crate::cli::text::{peer, time};
use crate::cli::{Env, Outcome};

fn snap_json(s: &pb::Snapshot) -> Value {
    json!({
        "name": peer(&s.name, 96),
        "kind": enum_name!(pb::SnapshotKind, s.kind, "SNAPSHOT_KIND_"),
        "created_unix_s": s.created_unix_s,
        "size_bytes": s.size_bytes,
    })
}

fn mib(bytes: u64) -> String {
    format!("{:.1} MiB", bytes as f64 / (1024.0 * 1024.0))
}

pub(super) fn list(env: &mut Env<'_>, id: &str) -> Result<Outcome, CliError> {
    let mut p = privd(env)?;
    let snaps = match p.simple(Command::ListSnapshots(pb::ListSnapshotsRequest {
        desktop_id: id.to_owned(),
    }))? {
        R::ListSnapshots(r) => r.snapshots,
        _ => return Err(unexpected("ListSnapshots")),
    };
    let mut t = String::new();
    if snaps.is_empty() {
        t.push_str("no snapshots\n");
    } else {
        t.push_str(
            "NAME                                   KIND       CREATED               SIZE\n",
        );
        for s in &snaps {
            t.push_str(&format!(
                "{:<38}  {:<9}  {:<20}  {}\n",
                peer(&s.name, 96),
                enum_name!(pb::SnapshotKind, s.kind, "SNAPSHOT_KIND_").to_lowercase(),
                time(s.created_unix_s),
                mib(s.size_bytes)
            ));
        }
    }
    Ok(Outcome::ok(
        t,
        json!({"desktop": id, "snapshots": snaps.iter().map(snap_json).collect::<Vec<_>>()}),
    ))
}

pub(super) fn create(env: &mut Env<'_>, id: &str) -> Result<Outcome, CliError> {
    let mut p = privd(env)?;
    let s = match p.simple(Command::CreateSnapshot(pb::CreateSnapshotRequest {
        desktop_id: id.to_owned(),
    }))? {
        R::CreateSnapshot(r) => r.snapshot.unwrap_or_default(),
        _ => return Err(unexpected("CreateSnapshot")),
    };
    Ok(Outcome::ok(
        format!("created snapshot {}\n", peer(&s.name, 96)),
        json!({"desktop": id, "snapshot": snap_json(&s)}),
    ))
}

pub(super) fn delete(env: &mut Env<'_>, id: &str, name: &str) -> Result<Outcome, CliError> {
    let mut p = privd(env)?;
    match p.simple(Command::DeleteSnapshot(pb::DeleteSnapshotRequest {
        desktop_id: id.to_owned(),
        name: name.to_owned(),
    }))? {
        R::DeleteSnapshot(_) => {}
        _ => return Err(unexpected("DeleteSnapshot")),
    }
    Ok(Outcome::ok(
        format!("deleted snapshot {name} (or it was already gone)\n"),
        json!({"desktop": id, "deleted": name}),
    ))
}
